/* ---------- Image generation ---------- */
/* a prompt and what it made on the left, earlier pictures and style presets on the right (owner, 5 Nov). Each picture is
   made in three stages, the way an image model works: Composing (a grid of dots in the picture's colours grows out of
   grain), Adding detail (the blur lifts step by step while a scan line sweeps down and leaves the detailed picture behind
   it) and Upscaling (the last softness and grain go). The steps are a model's denoising steps: the picture changes a step
   at a time and eases between them. Every picture moves at its own speed, and one can fail with Retry. Upscale sweeps the
   line down once more over a softened copy. Blueprint never blurs: its dots are square cells, the picture shows through
   them at half strength, and its scan line is the accent's mark. With reduced motion a picture fades in once it is done.
   --dm-ar is a picture's width over its height, --dm-art the gradient of its colours that stands in for it; on a picture being
   made, --dm-dot (Blueprint: --dm-sq) is the size of its dots, --dm-bl the blur, --dm-gr the grain, --dm-sc how far the scan has come and
   --dm-stp how long a step takes */
.card.wide .stage-in:has(>.igx){max-width:900px}
.igx{width:100%;container:igx/inline-size;text-align:left}
.igx-in{position:relative;display:grid;grid-template-columns:minmax(0,1fr) 252px;gap:var(--dm-s-3);height:572px}
.igx-main,.igx-side{min-width:0;min-height:0;display:flex;flex-direction:column;background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow);overflow:hidden}
.igx-h{flex:none;display:flex;align-items:center;gap:var(--dm-s-2);height:44px;padding:0 var(--dm-s-2) 0 var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px}
.igx-cr{flex:1;min-width:0;display:flex;align-items:center;gap:2px;white-space:nowrap;color:var(--dm-muted)}
.igx-cr .i{color:var(--dm-faint);flex:none}
.igx-cr b{min-width:0;font-weight:500;color:var(--dm-fg);overflow:hidden;text-overflow:ellipsis}
.igx-vw{display:none}
/* the feed: the prompt as sent, then what it made */
.igx-feed{flex:1;min-height:0;display:flex;flex-direction:column;gap:var(--dm-s-3);padding:var(--dm-s-4) var(--dm-s-4) var(--dm-s-2)}
.igx-ask{flex:none;max-width:88%;font-size:13.5px;line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.igx-ask:empty{display:none}
.igx-run{flex:1;min-height:0;display:flex;flex-direction:column;gap:10px}
.igx-run[hidden]{display:none}
.igx-rh{flex:none;display:flex;align-items:center;gap:var(--dm-s-3);min-height:20px;font-size:13px}
.igx-rt{flex:1;min-width:0;display:flex;align-items:center;gap:var(--dm-s-2);white-space:nowrap}
.igx-rt>span{min-width:0;overflow:hidden;text-overflow:ellipsis}
.igx-rt .i{color:var(--dm-fg2)}
.igx-rt .spin{width:11px;height:11px;color:var(--dm-fg2)}
/* the three stages and how far the run has come: the stage in hand is ink, the ones done are ticked */
.igx-steps{flex:none;display:flex;align-items:center;gap:10px;font-size:12px;color:var(--dm-muted);white-space:nowrap}
.igx-steps span{display:inline-flex;align-items:center;gap:5px;transition:color var(--dm-t-fast)}
.igx-steps i{width:6px;height:6px;border-radius:50%;background:var(--dm-rail);transition:background var(--dm-t-fast)}
.igx-steps .on{color:var(--dm-fg)}
.igx-steps .on i{background:var(--dm-fg2)}
.igx-steps .done{color:var(--dm-fg2)}
.igx-steps .done i{display:none}
.igx-steps .i{display:none;width:12px;height:12px}
.igx-steps .done .i{display:inline-block}
.igx-pc{flex:none;min-width:34px;font-size:12px;color:var(--dm-fg2);text-align:right}
/* the pictures share the room left, as large as their shape and number allow: --dm-cols and --dm-rows are the layout that
   gives each the most room, measured by the script */
.igx-tiles{flex:1;min-height:0;display:flex;flex-wrap:wrap;align-content:center;justify-content:center;gap:var(--dm-s-2);container-type:size}
.igx-t{position:relative;flex:none;margin:0;width:min(calc((100cqw - (var(--dm-cols,1) - 1) * var(--dm-s-2)) / var(--dm-cols,1)),calc((100cqh - (var(--dm-rows,1) - 1) * var(--dm-s-2)) / var(--dm-rows,1) * var(--dm-ar,1)));aspect-ratio:var(--dm-ar,1);border-radius:var(--dm-r-in);overflow:hidden;isolation:isolate;background:var(--dm-row);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
.igx-o{position:absolute;inset:0;width:100%;height:100%;display:block;border-radius:inherit;cursor:zoom-in}
.igx-o:disabled{cursor:default}
.igx-o:focus-visible{outline-offset:-2px}
.igx-ly{position:absolute;inset:0;background-image:var(--dm-art);background-size:cover;background-position:center;pointer-events:none}
/* the base: the picture's colours, soft, seen through the dots while it is composed */
.igx-b{transform:scale(calc(1.14 * var(--dm-vz,1)));transform-origin:var(--dm-vo,50% 50%);filter:blur(var(--dm-bl,18px)) saturate(1.3);opacity:0;transition:filter var(--dm-stp,.2s) linear,opacity .5s var(--dm-ease)}
.igx-t:is([data-st="gen"],[data-st="fail"]) .igx-b{opacity:1}
.igx-t[data-st="gen"] .igx-b{-webkit-mask:radial-gradient(circle,#000 var(--dm-dot,1px),transparent calc(var(--dm-dot,1px) + 1px)) 50% 50%/var(--dm-cell,12px) var(--dm-cell,12px);mask:radial-gradient(circle,#000 var(--dm-dot,1px),transparent calc(var(--dm-dot,1px) + 1px)) 50% 50%/var(--dm-cell,12px) var(--dm-cell,12px)}
.igx-t[data-st="fail"] .igx-b{filter:blur(var(--dm-bl,18px)) grayscale(1);opacity:.55}
/* the detailed picture, uncovered by the scan */
.igx-s{transform:scale(var(--dm-vz,1));transform-origin:var(--dm-vo,50% 50%);clip-path:inset(0 0 calc(100% - var(--dm-sc,1) * 100%) 0);filter:blur(var(--dm-sb,0px));transition:clip-path var(--dm-stp,.2s) linear,filter var(--dm-stp,.2s) linear,opacity .5s var(--dm-ease)}
.igx-t:is([data-st="wait"],[data-st="fail"]) .igx-s{opacity:0}
/* grain, which fades as the picture settles */
.igx-n{position:absolute;inset:0;pointer-events:none;background-image:var(--dm-noise,none);background-size:96px 96px;opacity:var(--dm-gr,0);transition:opacity var(--dm-stp,.2s) linear}
.igx-t:is([data-st="wait"],[data-st="gen"]) .igx-n{animation:igxgr .48s steps(1,end) infinite}
.igx-t[data-st="wait"] .igx-n{opacity:.5}
@keyframes igxgr{0%{background-position:0 0}25%{background-position:-31px 17px}50%{background-position:23px -41px}75%{background-position:-13px -29px}}
/* the scan line: a thin light with a faint wash above it */
.igx-l{position:absolute;inset:0;pointer-events:none;opacity:0;transform:translateY(calc(var(--dm-sc,0) * 100%));transition:transform var(--dm-stp,.2s) linear,opacity .3s}
.igx-l>span{position:absolute;left:0;right:0}
.igx-l>span:first-child{top:-1px;height:2px;background:rgba(255,255,255,.92)}
.igx-l>span:last-child{bottom:100%;height:32px;background:linear-gradient(rgba(255,255,255,0),rgba(255,255,255,.22))}
.igx-t[data-st="gen"] .igx-l{opacity:var(--dm-lo,0)}
/* Upscale: the picture softens, and the line sweeps down once leaving it sharp */
.igx-t.up .igx-b{opacity:1;-webkit-mask:none;mask:none;filter:blur(3px);transition:none}
.igx-t.up .igx-s{animation:igxrv 1.6s var(--dm-ease-io) both}
.igx-t.up .igx-l{animation:igxsc 1.6s var(--dm-ease-io) both}
@keyframes igxrv{from{clip-path:inset(0 0 100% 0)}to{clip-path:inset(0)}}
@keyframes igxsc{from{opacity:1;transform:translateY(0)}88%{opacity:1}to{opacity:0;transform:translateY(100%)}}
/* how far a picture has come, until it is done */
.igx-tp{position:absolute;left:var(--dm-s-2);bottom:var(--dm-s-2);height:20px;padding:0 7px;display:inline-flex;align-items:center;border-radius:var(--dm-r-tag);background:color-mix(in srgb,var(--dm-surface) 90%,transparent);color:var(--dm-fg);font-size:11.5px;font-weight:500;opacity:0;transition:opacity .3s;pointer-events:none}
.igx-t:is([data-st="wait"],[data-st="gen"]) .igx-tp{opacity:1}
.igx-tg{position:absolute;left:6px;top:6px;background:color-mix(in srgb,var(--dm-surface) 90%,transparent);color:var(--dm-fg);pointer-events:none}
.igx-tg:empty{display:none}
/* a picture that failed: what happened and Retry, over its faded colours */
.igx-f{position:absolute;inset:0;display:none;flex-direction:column;align-items:center;justify-content:center;gap:var(--dm-s-1);padding:var(--dm-s-2);text-align:center;background:color-mix(in srgb,var(--dm-surface) 84%,transparent);font-size:12px;line-height:1.35;color:var(--dm-fg2)}
.igx-t[data-st="fail"] .igx-f{display:flex}
.igx-f>.i{color:var(--dm-bad)}
.igx-f b{font-size:12.5px;font-weight:500;color:var(--dm-fg)}
.igx-f .pill{margin-top:var(--dm-s-1)}
/* quick actions on a finished picture, under the pointer or the keyboard */
.igx-q{position:absolute;right:6px;bottom:6px;display:flex;gap:2px;padding:2px;border-radius:calc(11px * var(--dm-rk));background:color-mix(in srgb,var(--dm-surface) 94%,transparent);box-shadow:var(--dm-shadow);opacity:0;transform:translateY(4px);pointer-events:none;transition:opacity var(--dm-t-fast),transform var(--dm-t-fast) var(--dm-ease)}
.igx-q .ib{width:28px;height:28px}
@media (hover:hover) and (pointer:fine){.igx-t[data-st="done"]:hover .igx-q{opacity:1;transform:none;pointer-events:auto}}
.igx-t[data-st="done"]:is(:focus-within,.hov) .igx-q{opacity:1;transform:none;pointer-events:auto}
/* under the pictures: rate them, copy the prompt, and what made them */
.igx-acts{flex:none;display:flex;align-items:center;gap:2px;min-height:30px;margin-left:-6px}
.igx-acts .ib[aria-pressed="true"],.igx-lb .ib[aria-pressed="true"]{background:var(--dm-chip);color:var(--dm-fg)}
.igx-sep{flex:none;width:1px;height:16px;margin:0 6px;background:color-mix(in srgb,var(--dm-line) 100%,transparent)}
.igx-meta{flex:1;min-width:0;font-size:12px;color:var(--dm-muted);text-align:right;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* before anything is made */
.igx-empty{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:var(--dm-s-3);font-size:13px;color:var(--dm-muted);text-align:center}
.igx-empty[hidden]{display:none}
.igx-ef{display:flex;gap:var(--dm-s-2)}
.igx-ef span{width:40px;aspect-ratio:3/4;display:grid;place-items:center;border-radius:var(--dm-r-sm);background:var(--dm-row);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-faint)}
.igx-ef span:nth-child(2){transform:translateY(-6px)}
/* the composer: references, the prompt, its styles, and the settings for the run */
.igx-cmp{flex:none;margin:0 var(--dm-s-3) var(--dm-s-3);display:flex;flex-direction:column;border-radius:var(--dm-r-box);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);transition:box-shadow var(--dm-t-fast)}
.igx-cmp:focus-within{box-shadow:inset 0 0 0 1px var(--dm-field-line-strong)}
.igx-refs{display:flex;flex-wrap:wrap;gap:6px;padding:10px var(--dm-s-3) 0}
.igx-refs:empty{display:none}
.igx-ref{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 var(--dm-s-1) 0 3px;border-radius:var(--dm-r-tag);background:var(--dm-chip);font-size:12px;color:var(--dm-fg2);white-space:nowrap}
.igx-ref .igx-rp{position:relative;width:20px;height:20px;border-radius:calc(5px * var(--dm-rk));overflow:hidden;background:var(--dm-row)}
.igx-ref .ib{width:20px;height:20px}
.igx-ta{display:block;width:100%;height:58px;border:0;outline:0;resize:none;background:none;color:var(--dm-fg);font:inherit;font-size:14px;line-height:1.45;padding:var(--dm-s-3) var(--dm-s-3) 2px}
.igx-ta::placeholder{color:var(--dm-muted)}
.igx-sty{display:flex;flex-wrap:wrap;gap:6px;padding:6px var(--dm-s-3) 0}
/* a style chip is a white tile with a dimmed edge; picked, its edge steps up and a tick slides in */
.igx-sc{display:inline-flex;align-items:center;gap:0;height:26px;padding:0 10px;border-radius:var(--dm-r-tag);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 100%,transparent);font-size:12.5px;color:var(--dm-fg2);white-space:nowrap;transition:background var(--dm-t-fast),color var(--dm-t-fast),box-shadow var(--dm-t-fast),gap var(--dm-t) var(--dm-ease)}
.igx-sc .i{width:0;opacity:0;transition:width var(--dm-t) var(--dm-ease),opacity var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.igx-sc:hover{background:var(--dm-row);color:var(--dm-fg)}}
.igx-sc[aria-pressed="true"]{gap:5px;color:var(--dm-fg);box-shadow:inset 0 0 0 1px var(--dm-faint)}
.igx-sc[aria-pressed="true"] .i{width:12px;opacity:1}
.igx-sc.hl{background:var(--dm-row)}
.igx-bar{display:flex;align-items:center;gap:var(--dm-s-1);padding:var(--dm-s-2) var(--dm-s-2) var(--dm-s-2) 6px}
.igx-bar .chip{height:32px;padding:0 10px;gap:6px;background:none;min-width:0;font-size:13px;color:var(--dm-fg2)}
.igx-bar .chip[aria-expanded="true"]{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.igx-bar .chip:hover{background:var(--dm-row);color:var(--dm-fg)}}
.igx-bar .chip>span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.igx-bar .chip>.i:last-child{color:var(--dm-muted)}
.igx-bar .sp{flex:1}
.igx-go{flex:none}
/* the settings: shape and how many, two switches in a small panel */
.igx-pp-set{min-width:236px;padding:var(--dm-s-2) 10px 10px}
.igx-pp-set .ph{padding:var(--dm-s-1) 0 6px}
.igx-pp-set .seg2{display:flex;margin-bottom:var(--dm-s-1)}
.igx-pp-set .seg2 button{flex:1}
/* the side: earlier pictures and style presets */
.igx-sh{flex:none;display:flex;align-items:center;gap:var(--dm-s-2);height:44px;padding:0 var(--dm-s-2);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.igx-sh .sp{flex:1}
.igx-sh .muted{font-size:12px;padding-right:6px}
.igx-pane{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;padding:var(--dm-s-2)}
.igx-pane[hidden]{display:none}
.igx-pane:focus-visible{outline-offset:-2px}
/* the gallery: two columns, each picture in its own shape, the newest first */
.igx-gal{display:flex;gap:6px;align-items:flex-start}
.igx-col{flex:1;min-width:0;display:flex;flex-direction:column;gap:6px}
.igx-g{position:relative;display:block;width:100%;aspect-ratio:var(--dm-ar,1);border-radius:var(--dm-r-sm);overflow:hidden;background:var(--dm-row);cursor:zoom-in;transition:opacity var(--dm-t-fast)}
.igx-g .igx-ly{transform:scale(var(--dm-vz,1));transform-origin:var(--dm-vo,50% 50%);transition:transform .5s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.igx-g:hover .igx-ly{transform:scale(calc(var(--dm-vz,1) * 1.04))}}
.igx-g:focus-visible{outline-offset:-2px}
.igx-g.new{animation:igxnew .7s var(--dm-ease) both}
@keyframes igxnew{from{opacity:0;filter:blur(8px);transform:translateY(-8px)}to{opacity:1;filter:none;transform:none}}
:root:not([data-style="soft"]) .igx-g.new:not(:where([data-style="soft"],[data-style="soft"] *)){animation:igxwipe var(--dm-t-slow) var(--dm-ease) both}
@keyframes igxwipe{from{clip-path:inset(0 0 100% 0)}to{clip-path:inset(0)}}
/* the style presets: a picture and what it sets */
.igx-prs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}
.igx-pr{display:flex;flex-direction:column;gap:6px;padding:4px 4px 8px;border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 100%,transparent);text-align:left;transition:background var(--dm-t-fast),box-shadow var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.igx-pr:hover{background:var(--dm-row)}}
.igx-pr[aria-pressed="true"]{box-shadow:inset 0 0 0 1px var(--dm-faint)}
.igx-prp{position:relative;display:block;aspect-ratio:4/3;border-radius:var(--dm-r-sm);overflow:hidden;background:var(--dm-row)}
.igx-prt{display:flex;flex-direction:column;padding:0 4px;font-size:12.5px;line-height:1.35}
.igx-prt b{font-weight:500;color:var(--dm-fg)}
.igx-prt .muted{font-size:11.5px}
/* the larger view: over the whole component, the picture as large as it fits, with every action */
.igx-lb{position:absolute;inset:0;z-index:5;display:flex;flex-direction:column;border-radius:var(--dm-r-card);background:var(--dm-surface);box-shadow:var(--dm-shadow);overflow:hidden}
.igx-lb[hidden]{display:none}
.igx-lb.open{animation:igxlb .42s var(--dm-ease) both}
@keyframes igxlb{from{opacity:0}to{opacity:1}}
.igx-lb.open .igx-lbs>.igx-t{animation:igxlbp .6s var(--dm-ease) both}
@keyframes igxlbp{from{opacity:0;transform:scale(.94);filter:blur(10px)}to{opacity:1;transform:none;filter:none}}
:root:not([data-style="soft"]) .igx-lb.open:not(:where([data-style="soft"],[data-style="soft"] *)){animation:igxwipe var(--dm-t-slow) var(--dm-ease) both}
:root:not([data-style="soft"]) .igx-lb.open .igx-lbs>.igx-t:not(:where([data-style="soft"],[data-style="soft"] *)){animation:none}
.igx-lbh{flex:none;display:flex;align-items:center;gap:var(--dm-s-2);min-height:48px;padding:6px var(--dm-s-2) 6px var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.igx-lbt{flex:1;min-width:0;display:flex;flex-direction:column;font-size:13px;line-height:1.35}
.igx-lbt b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.igx-lbt .muted{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.igx-lbb{flex:1;min-height:0;display:flex;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-3) var(--dm-s-2)}
.igx-lbs{flex:1;min-width:0;height:100%;display:flex;align-items:center;justify-content:center;container-type:size}
.igx-lbs>.igx-t{width:min(100cqw,100cqh * var(--dm-ar,1));cursor:default}
.igx-lbn{flex:none;width:32px;padding:0}
@media (hover:hover) and (pointer:fine){.igx-lbn:not(:disabled):hover{background:var(--dm-row)}}
.igx-lbf{flex:none;display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:var(--dm-s-1);padding:var(--dm-s-2) var(--dm-s-3) var(--dm-s-3)}
.igx-lbf .igx-sep{margin:0 var(--dm-s-1)}
.igx-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
/* a narrower feed keeps only the stage in hand beside the title */
@container igx (max-width:780px){.igx-steps span:not(.on){display:none}}
/* between the two, the side gives the pictures a little more room, and a failed picture keeps only its title and Retry */
@container igx (max-width:820px){.igx-in{grid-template-columns:minmax(0,1fr) 212px}.igx-f>span{display:none}}
/* narrower: the gallery and the styles take the feed's place, picked in the header */
@container igx (max-width:620px){
  .igx-in{grid-template-columns:minmax(0,1fr);height:600px}
  .igx-main,.igx-side{grid-area:1/1}
  .igx-side{margin-top:45px;border-radius:0 0 var(--dm-r-card) var(--dm-r-card);box-shadow:none;visibility:hidden}
  .igx-sh{display:none}
  .igx-vw{display:inline-flex}
  .igx-cr{display:none}
  .igx-h{justify-content:space-between;padding-left:var(--dm-s-2)}
  .igx-in:is([data-view="gallery"],[data-view="styles"]) .igx-side{visibility:visible;z-index:2}
  .igx-in:is([data-view="gallery"],[data-view="styles"]) :is(.igx-feed,.igx-cmp){visibility:hidden}
  .igx-steps span:not(.on){display:none}
  .igx-pane{padding:var(--dm-s-3)}
  .igx-gal{gap:var(--dm-s-2)}.igx-col{gap:var(--dm-s-2)}
  .igx-prs{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@container igx (max-width:440px){
  .igx-in{height:640px}
  .igx-feed{padding:var(--dm-s-3) var(--dm-s-3) var(--dm-s-2)}
  .igx-ask{display:block;white-space:nowrap;text-overflow:ellipsis}
  .igx-sty{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;gap:var(--dm-s-1)}
  .igx-sty::-webkit-scrollbar{display:none}
  .igx-sc{flex:none;padding:0 var(--dm-s-2)}
